mapper.select:
SELECT A.FRM_UNQ_KY_VAL, B.TST_UNQ_KY_VAL, C.UNQ_KY_VAL, A.UNQ_ID, C.CHCK_YN, CASE WHEN C.CHCK_YN = 'Y' THEN '점검' WHEN C.CHCK_YN = '1' THEN '만족' WHEN C.CHCK_YN = '0' THEN '불만족' ELSE C.CHCK_YN END AS CHCK_YN_NM, A.TH1_ITM_NM, A.TH2_ITM_NM, A.TH3_ITM_NM, A.TITL_NM, C.REGPR_ID, C.REGPR_NM, C.RG_DT, TO_CHAR(C.RG_DT, 'YYYY-MM-DD HH24:MI:SS') AS FM_RG_DT, C.RMK_NM, (SELECT ATFL_GRUP_NM || '/' || ATFL_PHCL_NM || '.' || ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRMMNT_S' AND UNQ_NO = C.UNQ_KY_VAL AND ATFL_ID = '1') OZD_FNAME1, (SELECT ATFL_GRUP_NM || '/' || ATFL_PHCL_NM || '.' || ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = B.FRM_UNQ_KY_VAL AND ATFL_ID = '1') FNAME1, (SELECT ATFL_GRUP_NM || '/' || ATFL_PHCL_NM || '.' || ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = B.FRM_UNQ_KY_VAL AND ATFL_ID = '2') FNAME2, (SELECT ATFL_GRUP_NM || '/' || ATFL_PHCL_NM || '.' || ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = B.FRM_UNQ_KY_VAL AND ATFL_ID = '3') FNAME3, (SELECT ATFL_GRUP_NM || '/' || ATFL_PHCL_NM || '.' || ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = B.FRM_UNQ_KY_VAL AND ATFL_ID = '4') FNAME4, (SELECT ATFL_GRUP_NM || '/' || ATFL_PHCL_NM || '.' || ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = B.FRM_UNQ_KY_VAL AND ATFL_ID = '5') FNAME5 FROM GE_MP_FRMMNT_M A JOIN GE_MP_CHECK_S B ON A.FRM_UNQ_KY_VAL = B.FRM_UNQ_KY_VAL
AND B.TST_UNQ_KY_VAL = #{TST_UNQ_KY_VAL}
LEFT JOIN GE_MP_FRMMNT_S C ON C.TST_UNQ_KY_VAL = B.TST_UNQ_KY_VAL AND A.UNQ_ID = C.UNQ_ID WHERE 1 = 1
AND A.FRM_UNQ_KY_VAL = #{FRM_UNQ_KY_VAL}
AND A.TITL_NM LIKE '%'||#{SH_TITL_NM}||'%'
AND C.RMK_NM LIKE '%'||#{SH_RMK_NM}||'%'
AND C.CHCK_YN = #{CHCK_YN}
ORDER BY TITL_NM, TH1_ITM_NM, TH2_ITM_NM, TH3_ITM_NM

SELECT COUNT(*) FROM GE_MP_FRMMNT_M A JOIN GE_MP_CHECK_S B ON A.FRM_UNQ_KY_VAL = B.FRM_UNQ_KY_VAL
AND B.TST_UNQ_KY_VAL = #{TST_UNQ_KY_VAL}
LEFT JOIN GE_MP_FRMMNT_S C ON C.TST_UNQ_KY_VAL = B.TST_UNQ_KY_VAL AND A.UNQ_ID = C.UNQ_ID WHERE 1 = 1
AND A.FRM_UNQ_KY_VAL = #{FRM_UNQ_KY_VAL}
AND C.CHCK_YN IS NOT NULL

mapper.delete:
DELETE FROM GE_MP_FRMMNT_M
 WHERE FRM_UNQ_KY_VAL = ${FRM_UNQ_KY_VAL}
 AND   UNQ_ID =${UNQ_ID}

mapper.select:
SELECT TO_CHAR(A.MSNT_DT, 'YYYY-MM-DD HH24:MI:SS') AS FM_MSNT_DT, TO_CHAR(A.MSNT_DT, 'YYYY-MM-DD HH24:MI:SS') AS FM_RG_DT, A.AGMST_VAL FROM GE_MP_FRMID_S A JOIN GE_MP_CHECK_S B ON A.TST_UNQ_KY_VAL = B.TST_UNQ_KY_VAL WHERE 1 = 1
AND B.FRM_UNQ_KY_VAL = #{FRM_UNQ_KY_VAL}
AND A.FRM_ID = #{FRM_ID}
ORDER BY A.RG_DT DESC

SELECT B.FRM_UNQ_KY_VAL, B.TST_UNQ_KY_VAL, A.UNQ_KY_VAL, A.UNQ_ID, A.CHCK_YN, CASE WHEN A.CHCK_YN = 'Y' THEN '점검' WHEN A.CHCK_YN = '1' THEN '만족' WHEN A.CHCK_YN = '0' THEN '불만족' ELSE A.CHCK_YN END AS CHCK_YN_NM, A.TH1_ITM_NM, A.REGPR_ID, A.REGPR_NM, A.RG_DT, TO_CHAR(A.RG_DT, 'YYYY-MM-DD HH24:MI:SS') AS FM_RG_DT, A.RMK_NM, (SELECT ATFL_GRUP_NM || '/' || ATFL_PHCL_NM || '.' || ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRMMNT_S' AND UNQ_NO = A.UNQ_KY_VAL AND ATFL_ID = '1') OZD_NAME, (SELECT ATFL_GRUP_NM || '/' || ATFL_PHCL_NM || '.' || ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = B.FRM_UNQ_KY_VAL AND ATFL_ID = '1') FNAME1, (SELECT ATFL_GRUP_NM || '/' || ATFL_PHCL_NM || '.' || ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = B.FRM_UNQ_KY_VAL AND ATFL_ID = '2') FNAME2, (SELECT ATFL_GRUP_NM || '/' || ATFL_PHCL_NM || '.' || ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = B.FRM_UNQ_KY_VAL AND ATFL_ID = '3') FNAME3, (SELECT ATFL_GRUP_NM || '/' || ATFL_PHCL_NM || '.' || ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = B.FRM_UNQ_KY_VAL AND ATFL_ID = '4') FNAME4, (SELECT ATFL_GRUP_NM || '/' || ATFL_PHCL_NM || '.' || ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = B.FRM_UNQ_KY_VAL AND ATFL_ID = '5') FNAME5 FROM GE_MP_FRMMNT_S A JOIN GE_MP_CHECK_S B ON A.TST_UNQ_KY_VAL = B.TST_UNQ_KY_VAL
AND B.TST_UNQ_KY_VAL = #{TST_UNQ_KY_VAL}
WHERE 1 = 1
AND B.FRM_UNQ_KY_VAL = #{FRM_UNQ_KY_VAL}
AND A.RMK_NM LIKE '%'||#{SH_RMK_NM}||'%'
AND A.CHCK_YN = #{CHCK_YN}
ORDER BY TITL_NM, TH1_ITM_NM

SELECT COUNT(*) FROM GE_MP_FRMMNT_S A JOIN GE_MP_CHECK_S B ON A.TST_UNQ_KY_VAL = B.TST_UNQ_KY_VAL
AND B.TST_UNQ_KY_VAL = #{TST_UNQ_KY_VAL}
WHERE 1 = 1
AND B.FRM_UNQ_KY_VAL = #{FRM_UNQ_KY_VAL}
AND A.CHCK_YN IS NOT NULL

mapper.update:
UPDATE GE_MP_FRMMNT_S
   SET UNQ_ID = #{UNQ_ID},
       TH1_ITM_NM = #{TH1_ITM_NM},
       RMK_NM = #{RMK_NM}
 WHERE UNQ_KY_VAL = ${UNQ_KY_VAL}
